using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in config or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define tools available to the agent
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a given query. Returns a list of relevant snippets."),
    AIFunctionFactory.Create(
        ([Description("The note text to save")] string note) => noteService.AddNote(note),
        "take_note",
        "Saves a research note for later summarization. Use this to record key findings."),
    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "get_notes",
        "Retrieves all notes taken during the research session."),
};

// Create the agent
var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your goal is to thoroughly research a topic provided by the user.

    Follow this workflow:
    1. Break the topic into 2-3 key search queries
    2. Use web_search for each query to gather information
    3. Use take_note to record important findings from each search
    4. After researching, use get_notes to review all findings
    5. Provide a comprehensive summary of your research to the user

    Be thorough but concise. Always cite which searches yielded which findings.
    """);

Console.WriteLine("🔍 Research Agent Ready");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.WriteLine();

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    noteService.Clear();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        Options = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    };

    Console.WriteLine($"\n📚 Researching: {topic}\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");
}

Console.WriteLine("Goodbye!");

// --- Tool Implementations ---

/// <summary>
/// Simulates web search results. Replace with a real search API (Bing, Google, etc.) in production.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        // In production, replace with Bing Search API, Google Custom Search, or similar.
        // This implementation uses a placeholder that demonstrates the tool contract.
        await Task.Delay(100); // Simulate network latency

        return $"""
            Search results for: "{query}"

            1. [Web Result] Based on current knowledge, here are key points about '{query}':
               - This is a simulated search result. In production, integrate with a real search API
                 such as Bing Web Search API (Azure) or Google Custom Search JSON API.
               - To enable real search, set the BING_API_KEY environment variable and update WebSearchTool.

            2. [Web Result] Additional information about '{query}':
               - Replace this placeholder with actual API calls for real research capabilities.
               - The agent will still demonstrate the full tool-calling workflow with these simulated results.

            Note: Set BING_API_KEY environment variable to enable real web search.
            """;
    }
}

/// <summary>
/// In-memory note-taking service for the research agent.
/// </summary>
sealed class NoteService
{
    private readonly List<string> _notes = [];

    public string AddNote(string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"Note #{i + 1}: {n}"));
    }

    public void Clear() => _notes.Clear();
}

